import json, os
files = json.loads('{"index.html": "<!DOCTYPE html>\\n<html lang=\\"en\\">\\n<head>\\n<meta charset=\\"utf-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">\\n<title>Nightschool: learn skills under the stars</title>\\n<link rel=\\"icon\\" href=\\"data:image/svg+xml,<svg xmlns=\'http://www.w3.org/2000/svg\' viewBox=\'0 0 100 100\'><text y=\'.9em\' font-size=\'90\'>\\u2726</text></svg>\\">\\n<link href=\\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,400;12..96,600;12..96,800&display=swap\\" rel=\\"stylesheet\\">\\n<style>\\n:root{--ink:#14122b;--ink2:#1f1b40;--line:#3a3470;--paper:#f3eeff;--dim:#9b95c9;--gold:#ffd166;--teal:#4fd1c5;--coral:#ff6b8b}\\n*{box-sizing:border-box;margin:0}\\nbody{font-family:\\"Bricolage Grotesque\\",system-ui,sans-serif;background:var(--ink);color:var(--paper);line-height:1.5;min-height:100vh;\\nbackground-image:radial-gradient(1px 1px at 20% 30%,#fff8 50%,transparent),radial-gradient(1px 1px at 70% 20%,#fff6 50%,transparent),radial-gradient(1.5px 1.5px at 40% 80%,#fff7 50%,transparent),radial-gradient(1px 1px at 88% 66%,#fff6 50%,transparent),radial-gradient(ellipse at 80% -10%,#3b2d8a66,transparent 55%);\\nbackground-size:260px 260px,340px 340px,300px 300px,220px 220px,100% 100%}\\nbutton{font:inherit;color:inherit;cursor:pointer}\\n:focus-visible{outline:2px solid var(--teal);outline-offset:3px}\\n.wrap{max-width:1120px;margin:0 auto;padding:0 20px}\\nheader{display:flex;flex-wrap:wrap;gap:16px;align-items:center;justify-content:space-between;padding:20px 0}\\n.brand{font-weight:800;font-size:1.4rem;letter-spacing:-.02em}\\n.brand span{color:var(--gold)}\\n.me{display:flex;align-items:center;gap:14px;background:var(--ink2);border:1px solid var(--line);border-radius:999px;padding:8px 8px 8px 18px}\\n.me b{font-weight:600}\\n.bar{width:120px;height:8px;background:var(--ink);border-radius:9px;overflow:hidden}\\n.bar i{display:block;height:100%;width:0;background:linear-gradient(90deg,var(--teal),var(--gold));transition:width .6s}\\n.streak{background:var(--ink);border-radius:999px;padding:4px 12px;font-size:.9rem}\\nh1{font-size:clamp(2.2rem,6vw,4.4rem);font-weight:800;line-height:1;letter-spacing:-.035em;max-width:14ch;margin:24px 0 12px}\\n.lede{color:var(--dim);max-width:52ch;font-size:1.05rem}\\n.tabs{display:flex;gap:8px;margin:28px 0 12px;flex-wrap:wrap}\\n.tab{background:none;border:1px solid var(--line);border-radius:999px;padding:8px 18px;transition:.2s}\\n.tab[aria-pressed=true]{background:var(--paper);color:var(--ink);border-color:var(--paper);font-weight:600}\\n.stage{display:grid;grid-template-columns:1fr 300px;gap:16px}\\n.map{background:#0e0c22aa;border:1px solid var(--line);border-radius:28px;overflow:hidden}\\nsvg{display:block;width:100%;height:auto}\\n.edge{stroke:var(--line);stroke-width:2;stroke-dasharray:5 6}\\n.edge.on{stroke:var(--gold);stroke-dasharray:none;stroke-width:2.5;filter:drop-shadow(0 0 4px var(--gold))}\\n.node{cursor:pointer}\\n.node .core{fill:var(--ink2);stroke:var(--dim);stroke-width:2;transition:.3s}\\n.node text{fill:var(--dim);font-size:15px;font-weight:600;text-anchor:middle;pointer-events:none}\\n.node.open .core{stroke:var(--teal);animation:pulse 2s infinite}\\n.node.open text{fill:var(--paper)}\\n.node.done .core{fill:var(--gold);stroke:var(--gold);filter:drop-shadow(0 0 10px var(--gold))}\\n.node.done text{fill:var(--gold)}\\n.node.sel .core{stroke:var(--coral);stroke-width:4}\\n@keyframes pulse{50%{stroke-width:6;stroke-opacity:.4}}\\n.spark{fill:var(--gold);animation:fly .9s ease-out forwards}\\n@keyframes fly{to{transform:translate(var(--dx),var(--dy));opacity:0}}\\n.panel,.card{background:var(--ink2);border:1px solid var(--line);border-radius:28px;padding:24px}\\n.panel h2{font-size:1.6rem;letter-spacing:-.02em}\\n.panel p{color:var(--dim);margin:8px 0 16px}\\n.tag{display:inline-block;background:var(--ink);border-radius:999px;padding:2px 12px;font-size:.85rem;margin-bottom:10px}\\n.btn{background:var(--gold);color:var(--ink);border:0;border-radius:14px;padding:12px 18px;font-weight:700;width:100%;transition:transform .15s}\\n.btn:hover{transform:translateY(-2px)}\\n.btn[disabled]{background:var(--line);color:var(--dim);cursor:not-allowed;transform:none}\\n.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin:16px 0 40px}\\n.orbit{display:flex;gap:24px;align-items:center;flex-wrap:wrap}\\n.ring{position:relative;width:150px;height:150px;flex:none}\\n.ring svg{transform:rotate(-90deg)}\\n.ring circle{fill:none;stroke-width:8}\\n.ring .bg{stroke:var(--ink)}\\n.ring .fg{stroke:var(--teal);stroke-linecap:round;transition:stroke-dashoffset 1s linear}\\n.ring .t{position:absolute;inset:0;display:grid;place-items:center;font-size:2rem;font-weight:800}\\n.modes{display:flex;gap:6px;margin-bottom:12px}\\n.modes button{background:var(--ink);border:1px solid var(--line);border-radius:10px;padding:4px 12px}\\n.modes button[aria-pressed=true]{border-color:var(--teal);color:var(--teal)}\\n.row{display:flex;gap:8px}\\n.ghost{background:none;border:1px solid var(--line);border-radius:14px;padding:12px 16px}\\n.card h3{font-size:1.3rem;margin-bottom:6px}\\n.card .sub{color:var(--dim);margin-bottom:16px}\\n.quest{font-size:1.25rem;font-weight:600;line-height:1.3;margin-bottom:16px;min-height:3.9em}\\n.quest.ok{color:var(--teal);text-decoration:line-through}\\n.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,120px);background:var(--paper);color:var(--ink);padding:12px 22px;border-radius:14px;font-weight:600;transition:transform .35s;z-index:9}\\n.toast.show{transform:translate(-50%,0)}\\nfooter{color:var(--dim);padding:0 0 40px;font-size:.9rem;display:flex;justify-content:space-between;flex-wrap:wrap;gap:8px}\\nfooter button{background:none;border:0;color:var(--dim);text-decoration:underline}\\n@media(max-width:860px){.stage,.grid{grid-template-columns:1fr}}\\n@media(prefers-reduced-motion:reduce){*{animation:none!important;transition:none!important}}\\n</style>\\n</head>\\n<body>\\n<div class=\\"wrap\\">\\n<header>\\n  <div class=\\"brand\\">Night<span>school</span></div>\\n  <a href=\\"learn.html\\" style=\\"color:var(--gold);font-weight:600\\">Open the learn zone: read, quiz, play</a>\\n  <div class=\\"me\\" aria-live=\\"polite\\">\\n    <b id=\\"title\\">Stargazer</b><span id=\\"lvl\\">Level 1</span>\\n    <div class=\\"bar\\" role=\\"progressbar\\" aria-label=\\"XP to next level\\"><i id=\\"xpbar\\"></i></div>\\n    <span class=\\"streak\\" id=\\"streak\\">0 day streak</span>\\n  </div>\\n</header>\\n\\n<h1>Learn one star at a time.</h1>\\n<p class=\\"lede\\">Pick a constellation, light up each skill in order, and turn your study time into XP. Your progress stays in this browser.</p>\\n\\n<div class=\\"tabs\\" id=\\"tabs\\" role=\\"group\\" aria-label=\\"Constellations\\"></div>\\n\\n<div class=\\"stage\\">\\n  <div class=\\"map\\"><svg id=\\"sky\\" viewBox=\\"0 0 800 460\\" role=\\"img\\" aria-label=\\"Skill constellation\\"></svg></div>\\n  <aside class=\\"panel\\" id=\\"panel\\"></aside>\\n</div>\\n\\n<div class=\\"grid\\">\\n  <section class=\\"card\\">\\n    <h3>Focus orbit</h3>\\n    <p class=\\"sub\\">Finish a session to earn 1 XP per minute.</p>\\n    <div class=\\"orbit\\">\\n      <div class=\\"ring\\">\\n        <svg viewBox=\\"0 0 120 120\\"><circle class=\\"bg\\" cx=\\"60\\" cy=\\"60\\" r=\\"54\\"/><circle class=\\"fg\\" id=\\"fg\\" cx=\\"60\\" cy=\\"60\\" r=\\"54\\"/></svg>\\n        <div class=\\"t\\" id=\\"clock\\">25:00</div>\\n      </div>\\n      <div>\\n        <div class=\\"modes\\" id=\\"modes\\"></div>\\n        <div class=\\"row\\"><button class=\\"btn\\" id=\\"go\\" style=\\"width:auto\\">Start session</button><button class=\\"ghost\\" id=\\"rst\\">Reset</button></div>\\n      </div>\\n    </div>\\n  </section>\\n  <section class=\\"card\\">\\n    <h3>Today\'s spark</h3>\\n    <p class=\\"sub\\">A ten-minute challenge. Finish it for 15 XP.</p>\\n    <div class=\\"quest\\" id=\\"quest\\"></div>\\n    <div class=\\"row\\"><button class=\\"btn\\" id=\\"qdone\\" style=\\"width:auto\\">I did it</button><button class=\\"ghost\\" id=\\"qnew\\">Give me another</button></div>\\n  </section>\\n</div>\\n\\n<footer><span>Built with plain HTML, CSS and JavaScript.</span><button id=\\"reset\\">Reset all progress</button></footer>\\n</div>\\n<div class=\\"toast\\" id=\\"toast\\" role=\\"status\\"></div>\\n\\n<script>\\nconst $=s=>document.querySelector(s), NS=\\"http://www.w3.org/2000/svg\\";\\nconst TRACKS={\\n web:{name:\\"Web builder\\",nodes:[\\n  [\\"html\\",\\"HTML\\",100,350,[],40,\\"Structure a page with headings, lists, links and forms. Build a one-page bio today.\\"],\\n  [\\"css\\",\\"CSS\\",250,400,[\\"html\\"],45,\\"Style with flexbox and grid. Recreate a site you like, using only CSS.\\"],\\n  [\\"js\\",\\"JavaScript\\",300,250,[\\"html\\"],55,\\"Make pages react to clicks. Start with a counter, then a to-do list.\\"],\\n  [\\"git\\",\\"Git\\",130,160,[],40,\\"Save snapshots of your work: commit, branch, push. Push this very site.\\"],\\n  [\\"dom\\",\\"The DOM\\",470,310,[\\"js\\",\\"css\\"],50,\\"Select, change and create elements from code. Build a tiny quiz.\\"],\\n  [\\"react\\",\\"React\\",630,190,[\\"dom\\"],60,\\"Break interfaces into components that hold their own state.\\"],\\n  [\\"deploy\\",\\"Deploy\\",690,370,[\\"git\\",\\"dom\\"],50,\\"Put your site on the internet with GitHub Pages in five minutes.\\"]]},\\n data:{name:\\"Data explorer\\",nodes:[\\n  [\\"xl\\",\\"Spreadsheets\\",100,330,[],35,\\"Sort, filter and pivot. Clean one messy table from start to finish.\\"],\\n  [\\"sql\\",\\"SQL\\",250,400,[\\"xl\\"],50,\\"Ask databases questions with SELECT, JOIN and GROUP BY.\\"],\\n  [\\"py\\",\\"Python\\",290,230,[],50,\\"Variables, loops, functions. Solve five small puzzles.\\"],\\n  [\\"stat\\",\\"Statistics\\",130,130,[],45,\\"Mean, spread, and why a small sample can lie to you.\\"],\\n  [\\"pd\\",\\"Pandas\\",470,300,[\\"py\\",\\"sql\\"],55,\\"Load a CSV, group it, summarise it. Three lines can answer a lot.\\"],\\n  [\\"viz\\",\\"Charts\\",630,180,[\\"pd\\"],50,\\"Pick the chart that fits the question, then remove everything extra.\\"],\\n  [\\"ml\\",\\"Machine learning\\",690,360,[\\"pd\\",\\"stat\\"],65,\\"Train a simple model and measure it on data it has never seen.\\"]]},\\n design:{name:\\"Design maker\\",nodes:[\\n  [\\"type\\",\\"Typography\\",110,300,[],40,\\"Pair two typefaces and set a clear size scale. Less is louder.\\"],\\n  [\\"color\\",\\"Colour\\",250,400,[],40,\\"Build a five-colour palette and check its contrast.\\"],\\n  [\\"lay\\",\\"Layout\\",300,220,[\\"type\\"],50,\\"Use space, alignment and grids to guide the eye.\\"],\\n  [\\"brand\\",\\"Identity\\",140,120,[\\"type\\",\\"color\\"],50,\\"Design a logo mark and voice for an imaginary shop.\\"],\\n  [\\"fig\\",\\"Figma\\",480,320,[\\"color\\",\\"lay\\"],55,\\"Frames, auto layout and components. Redesign one app screen.\\"],\\n  [\\"ux\\",\\"User research\\",630,190,[\\"lay\\"],55,\\"Watch five people use your design and note where they hesitate.\\"],\\n  [\\"proto\\",\\"Prototyping\\",690,370,[\\"fig\\"],50,\\"Link screens into a clickable flow and test it with a friend.\\"]]}\\n};\\nconst QUESTS=[\\"Explain one thing you learned this week to a friend, without notes.\\",\\"Rebuild yesterday\'s exercise from memory.\\",\\"Find one error in your old work and fix it.\\",\\"Write five questions about your current topic, then answer them.\\",\\"Read one documentation page and try its first example.\\",\\"Teach a rubber duck what a function is.\\",\\"Sketch your current project on paper before touching the keyboard.\\",\\"Delete ten lines of your code and keep it working.\\",\\"Watch a tutorial at 1x speed and pause to predict the next step.\\",\\"Send one useful link about your topic to someone.\\",\\"Make something ugly and finish it. Polish comes next.\\",\\"Turn a tutorial\'s example into something about your own life.\\"];\\nconst TITLES=[\\"Stargazer\\",\\"Spark Catcher\\",\\"Comet Chaser\\",\\"Orbit Keeper\\",\\"Nova Maker\\",\\"Constellation Weaver\\",\\"Galaxy Mind\\"];\\nconst KEY=\\"nightschool-v1\\";\\nlet S=JSON.parse(localStorage.getItem(KEY)||\\"null\\")||{xp:0,done:{},streak:0,last:\\"\\",quest:0,qok:\\"\\"};\\nlet track=\\"web\\",sel=null;\\nconst save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};\\nconst day=(o=0)=>{const d=new Date();d.setDate(d.getDate()-o);return d.toDateString()};\\n\\nfunction toast(m){const t=$(\\"#toast\\");t.textContent=m;t.classList.add(\\"show\\");clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove(\\"show\\"),2600)}\\nfunction addXP(n,why){\\n  const before=Math.floor(S.xp/100);S.xp+=n;\\n  if(S.last!==day()){S.streak=S.last===day(1)?S.streak+1:1;S.last=day()}\\n  save();hud();\\n  toast(`+${n} XP \\u00b7 ${why}`);\\n  if(Math.floor(S.xp/100)>before)setTimeout(()=>toast(`Level ${Math.floor(S.xp/100)+1}: ${TITLES[Math.min(Math.floor(S.xp/100),TITLES.length-1)]}`),2700);\\n}\\nfunction hud(){\\n  const l=Math.floor(S.xp/100);\\n  $(\\"#title\\").textContent=TITLES[Math.min(l,TITLES.length-1)];\\n  $(\\"#lvl\\").textContent=\\"Level \\"+(l+1);\\n  $(\\"#xpbar\\").style.width=(S.xp%100)+\\"%\\";\\n  const live=S.last===day()||S.last===day(1)?S.streak:0;\\n  $(\\"#streak\\").textContent=`${live} day streak`;\\n}\\n\\nfunction state(n){\\n  if(S.done[n[0]])return\\"done\\";\\n  return n[4].every(r=>S.done[r])?\\"open\\":\\"locked\\";\\n}\\nfunction draw(){\\n  const T=TRACKS[track],sky=$(\\"#sky\\");sky.innerHTML=\\"\\";\\n  const by=Object.fromEntries(T.nodes.map(n=>[n[0],n]));\\n  T.nodes.forEach(n=>n[4].forEach(r=>{\\n    const a=by[r],l=document.createElementNS(NS,\\"line\\");\\n    l.setAttribute(\\"x1\\",a[2]);l.setAttribute(\\"y1\\",a[3]);l.setAttribute(\\"x2\\",n[2]);l.setAttribute(\\"y2\\",n[3]);\\n    l.setAttribute(\\"class\\",\\"edge\\"+(S.done[r]&&S.done[n[0]]?\\" on\\":\\"\\"));sky.appendChild(l);\\n  }));\\n  T.nodes.forEach(n=>{\\n    const st=state(n),g=document.createElementNS(NS,\\"g\\");\\n    g.setAttribute(\\"class\\",`node ${st}${sel===n[0]?\\" sel\\":\\"\\"}`);\\n    g.setAttribute(\\"tabindex\\",\\"0\\");g.setAttribute(\\"role\\",\\"button\\");\\n    g.setAttribute(\\"aria-label\\",`${n[1]}, ${st}`);\\n    g.innerHTML=`<circle class=\\"core\\" cx=\\"${n[2]}\\" cy=\\"${n[3]}\\" r=\\"${st===\\"done\\"?20:16}\\"/><text x=\\"${n[2]}\\" y=\\"${n[3]+40}\\">${n[1]}</text>`;\\n    const pick=()=>{sel=n[0];draw();panel()};\\n    g.onclick=pick;g.onkeydown=e=>{if(e.key===\\"Enter\\"||e.key===\\" \\"){e.preventDefault();pick()}};\\n    sky.appendChild(g);\\n  });\\n  const done=T.nodes.filter(n=>S.done[n[0]]).length;\\n  $(\\"#tabs\\").querySelectorAll(\\".tab\\").forEach(b=>b.setAttribute(\\"aria-pressed\\",b.dataset.k===track));\\n}\\nfunction panel(){\\n  const T=TRACKS[track],n=T.nodes.find(x=>x[0]===sel),p=$(\\"#panel\\");\\n  if(!n){\\n    const d=T.nodes.filter(x=>S.done[x[0]]).length;\\n    p.innerHTML=`<span class=\\"tag\\">${T.name}</span><h2>${d} of ${T.nodes.length} stars lit</h2><p>Tap a glowing teal star to see what to practise. Grey stars unlock when the stars linked to them are lit.</p>`;return;\\n  }\\n  const st=state(n),names=n[4].filter(r=>!S.done[r]).map(r=>T.nodes.find(x=>x[0]===r)[1]);\\n  p.innerHTML=`<span class=\\"tag\\">${n[5]} XP</span><h2>${n[1]}</h2><p>${n[6]}</p>\\n  <button class=\\"btn\\" id=\\"learn\\" ${st===\\"done\\"?\\"disabled\\":st===\\"locked\\"?\\"disabled\\":\\"\\"}>${st===\\"done\\"?\\"Star lit\\":st===\\"locked\\"?\\"Light \\"+names.join(\\" and \\")+\\" first\\":\\"I learned this\\"}</button>`;\\n  $(\\"#learn\\").onclick=()=>{\\n    if(state(n)!==\\"open\\")return;\\n    S.done[n[0]]=1;addXP(n[5],n[1]+\\" lit\\");\\n    draw();panel();burst(n[2],n[3]);\\n  };\\n}\\nfunction burst(x,y){\\n  const sky=$(\\"#sky\\");\\n  for(let i=0;i<14;i++){\\n    const c=document.createElementNS(NS,\\"circle\\"),a=i/14*6.28,r=50+Math.random()*50;\\n    c.setAttribute(\\"cx\\",x);c.setAttribute(\\"cy\\",y);c.setAttribute(\\"r\\",3);c.setAttribute(\\"class\\",\\"spark\\");\\n    c.style.setProperty(\\"--dx\\",Math.cos(a)*r+\\"px\\");c.style.setProperty(\\"--dy\\",Math.sin(a)*r+\\"px\\");\\n    sky.appendChild(c);setTimeout(()=>c.remove(),1000);\\n  }\\n}\\n$(\\"#tabs\\").innerHTML=Object.entries(TRACKS).map(([k,t])=>`<button class=\\"tab\\" data-k=\\"${k}\\" aria-pressed=\\"false\\">${t.name}</button>`).join(\\"\\");\\n$(\\"#tabs\\").onclick=e=>{const k=e.target.dataset.k;if(k){track=k;sel=null;draw();panel()}};\\n\\n/* focus orbit */\\nconst C=2*Math.PI*54,fg=$(\\"#fg\\");fg.style.strokeDasharray=C;\\nlet mins=25,left=25*60,tick=null,end=0;\\n$(\\"#modes\\").innerHTML=[5,15,25,45].map(m=>`<button data-m=\\"${m}\\" aria-pressed=\\"${m===25}\\">${m} min</button>`).join(\\"\\");\\nconst fmt=s=>String(Math.floor(s/60)).padStart(2,\\"0\\")+\\":\\"+String(s%60).padStart(2,\\"0\\");\\nfunction ring(){$(\\"#clock\\").textContent=fmt(left);fg.style.strokeDashoffset=C*(1-left/(mins*60))}\\nfunction stop(){clearInterval(tick);tick=null;$(\\"#go\\").textContent=\\"Start session\\"}\\n$(\\"#modes\\").onclick=e=>{const m=+e.target.dataset.m;if(!m||tick)return;mins=m;left=m*60;\\n  $(\\"#modes\\").querySelectorAll(\\"button\\").forEach(b=>b.setAttribute(\\"aria-pressed\\",+b.dataset.m===m));ring()};\\n$(\\"#go\\").onclick=()=>{\\n  if(tick){stop();return}\\n  end=Date.now()+left*1000;$(\\"#go\\").textContent=\\"Pause\\";\\n  tick=setInterval(()=>{\\n    left=Math.max(0,Math.round((end-Date.now())/1000));ring();\\n    document.title=left?`${fmt(left)} \\u00b7 Nightschool`:\\"Nightschool: learn skills under the stars\\";\\n    if(!left){stop();addXP(mins,\\"Focus session done\\");left=mins*60;ring()}\\n  },250);\\n};\\n$(\\"#rst\\").onclick=()=>{stop();left=mins*60;ring()};\\n\\n/* daily spark */\\nfunction quest(){\\n  const q=$(\\"#quest\\");q.textContent=QUESTS[S.quest%QUESTS.length];\\n  const ok=S.qok===day()+S.quest;q.classList.toggle(\\"ok\\",ok);$(\\"#qdone\\").disabled=ok;$(\\"#qdone\\").textContent=ok?\\"Done today\\":\\"I did it\\";\\n}\\n$(\\"#qdone\\").onclick=()=>{S.qok=day()+S.quest;addXP(15,\\"Spark finished\\");quest()};\\n$(\\"#qnew\\").onclick=()=>{S.quest=Math.floor(Math.random()*QUESTS.length);save();quest()};\\nif(!S.qseed||S.qseed!==day()){S.qseed=day();S.quest=Math.floor(Math.random()*QUESTS.length);save()}\\n\\n$(\\"#reset\\").onclick=()=>{if(confirm(\\"Erase all XP and lit stars?\\")){S={xp:0,done:{},streak:0,last:\\"\\",quest:0,qok:\\"\\"};save();sel=null;hud();draw();panel();quest()}};\\n\\nhud();draw();panel();quest();ring();\\n</script>\\n</body>\\n</html>\\n", "learn.html": "<!DOCTYPE html>\\n<html lang=\\"en\\">\\n<head>\\n<meta charset=\\"utf-8\\">\\n<meta name=\\"viewport\\" content=\\"width=device-width, initial-scale=1\\">\\n<title>Learn zone \\u00b7 Nightschool</title>\\n<link href=\\"https://fonts.googleapis.com/css2?family=Bricolage+Grotesque:opsz,wght@12..96,400;12..96,600;12..96,800&display=swap\\" rel=\\"stylesheet\\">\\n<style>\\n:root{--ink:#14122b;--ink2:#1f1b40;--line:#3a3470;--paper:#f3eeff;--dim:#9b95c9;--gold:#ffd166;--teal:#4fd1c5;--coral:#ff6b8b}\\n*{box-sizing:border-box;margin:0}\\nbody{font-family:\\"Bricolage Grotesque\\",system-ui,sans-serif;background:var(--ink);color:var(--paper);line-height:1.55;min-height:100vh;background-image:radial-gradient(ellipse at 80% -10%,#3b2d8a66,transparent 55%)}\\nbutton{font:inherit;color:inherit;cursor:pointer}\\n:focus-visible{outline:2px solid var(--teal);outline-offset:3px}\\n.wrap{max-width:860px;margin:0 auto;padding:0 20px 60px}\\nheader{display:flex;justify-content:space-between;align-items:center;padding:20px 0;flex-wrap:wrap;gap:10px}\\na{color:var(--gold);font-weight:600}\\nh1{font-size:clamp(2rem,5vw,3.2rem);font-weight:800;letter-spacing:-.03em;line-height:1.05;margin:8px 0 16px}\\n.pills{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}\\n.pill{background:none;border:1px solid var(--line);border-radius:999px;padding:7px 18px}\\n.pill[aria-pressed=true]{background:var(--paper);color:var(--ink);border-color:var(--paper);font-weight:600}\\n.card{background:var(--ink2);border:1px solid var(--line);border-radius:24px;padding:24px;margin-top:14px}\\n.card h2{font-size:1.4rem;margin-bottom:8px;letter-spacing:-.02em}\\n.card p{color:#d8d2f5;max-width:64ch;margin-bottom:10px}\\n.btn{background:var(--gold);color:var(--ink);border:0;border-radius:14px;padding:11px 18px;font-weight:700}\\n.btn[disabled]{background:var(--line);color:var(--dim);cursor:default}\\n.opt{display:block;width:100%;text-align:left;background:var(--ink);border:1px solid var(--line);border-radius:14px;padding:12px 16px;margin:8px 0;transition:.15s}\\n.opt:hover:not([disabled]){border-color:var(--teal)}\\n.opt.good{border-color:var(--teal);background:#4fd1c522}\\n.opt.bad{border-color:var(--coral);background:#ff6b8b22}\\n.why{color:var(--dim);margin:10px 0}\\n.meta{color:var(--dim);font-size:.95rem;margin-bottom:6px}\\n.board{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:14px}\\n.tile{aspect-ratio:1/.8;border-radius:16px;border:1px solid var(--line);background:var(--ink);font-weight:600;padding:6px;font-size:clamp(.75rem,2.6vw,1rem);display:grid;place-items:center;text-align:center;transition:.2s}\\n.tile.up{background:var(--paper);color:var(--ink)}\\n.tile.ok{background:var(--gold);color:var(--ink);border-color:var(--gold)}\\ninput{font:inherit;background:var(--ink);color:var(--paper);border:1px solid var(--line);border-radius:14px;padding:11px 16px;width:100%;margin:10px 0}\\n.scr{font-size:2.2rem;font-weight:800;letter-spacing:.2em;margin:8px 0;color:var(--gold);word-break:break-all}\\n.toast{position:fixed;left:50%;bottom:24px;transform:translate(-50%,120px);background:var(--paper);color:var(--ink);padding:12px 22px;border-radius:14px;font-weight:600;transition:transform .35s}\\n.toast.show{transform:translate(-50%,0)}\\n</style>\\n</head>\\n<body>\\n<div class=\\"wrap\\">\\n<header><a href=\\"index.html\\">Back to the constellations</a><span id=\\"xp\\" class=\\"meta\\"></span></header>\\n<h1>Learn zone</h1>\\n<div class=\\"pills\\" id=\\"subj\\" role=\\"group\\" aria-label=\\"Subject\\"></div>\\n<div class=\\"pills\\" id=\\"tabs\\" role=\\"group\\" aria-label=\\"Section\\"></div>\\n<main id=\\"view\\"></main>\\n</div>\\n<div class=\\"toast\\" id=\\"toast\\" role=\\"status\\"></div>\\n\\n<script>\\nconst $=s=>document.querySelector(s);\\nconst SUBJ={web:\\"Web builder\\",data:\\"Data explorer\\",design:\\"Design maker\\"};\\nconst D={\\nweb:{\\n read:[[\\"HTML gives a page its skeleton\\",\\"HTML wraps content in tags. Headings, paragraphs, lists, links and forms each have a tag. Use meaningful tags such as nav, main and button, so browsers and screen readers understand your page.\\"],\\n       [\\"Flexbox and Grid\\",\\"Flexbox lays items out in one direction and is ideal for menus and rows. Grid handles rows and columns together, so it suits whole page layouts. Many layouts use both.\\"]],\\n quiz:[[\\"Which CSS declaration creates a flex container?\\",[\\"display: flex\\",\\"flex: container\\",\\"layout: flex\\",\\"position: flex\\"],0,\\"display: flex turns an element into a flex container.\\"],\\n       [\\"What does git commit do?\\",[\\"Uploads to GitHub\\",\\"Saves a snapshot in your local repo\\",\\"Deletes old files\\",\\"Starts a server\\"],1,\\"Commit records a snapshot locally. Push is what uploads it.\\"],\\n       [\\"Which is NOT a separate JavaScript type?\\",[\\"string\\",\\"boolean\\",\\"float\\",\\"undefined\\"],2,\\"JavaScript has one number type, so there is no float type.\\"],\\n       [\\"What is the DOM?\\",[\\"A database\\",\\"The page as a tree of objects\\",\\"A CSS file\\",\\"A web server\\"],1,\\"The browser turns your HTML into a tree that JavaScript can change.\\"],\\n       [\\"Which tag creates a link?\\",[\\"<link>\\",\\"<a>\\",\\"<href>\\",\\"<url>\\"],1,\\"The anchor tag a, with an href attribute, makes links.\\"]],\\n pairs:[[\\"HTML\\",\\"Page structure\\"],[\\"CSS\\",\\"Page style\\"],[\\"JS\\",\\"Page behaviour\\"],[\\"Git\\",\\"Version history\\"],[\\"DOM\\",\\"Page as objects\\"],[\\"Flexbox\\",\\"One-way layout\\"],[\\"Grid\\",\\"Rows and columns\\"],[\\"API\\",\\"How programs talk\\"]],\\n words:[[\\"FLEXBOX\\",\\"A CSS layout tool\\"],[\\"BRANCH\\",\\"A parallel line of commits\\"],[\\"SELECTOR\\",\\"Picks elements to style\\"],[\\"FUNCTION\\",\\"Reusable block of code\\"],[\\"COMMIT\\",\\"A saved snapshot\\"]]},\\ndata:{\\n read:[[\\"Mean, median and the outlier problem\\",\\"The mean is the average. The median is the middle value once sorted. One extreme value drags the mean but barely moves the median, so check both before you trust a summary.\\"],\\n       [\\"Asking a database with SQL\\",\\"SELECT chooses columns, WHERE filters rows, GROUP BY summarises groups and JOIN combines tables. Read a query in that order and it becomes a sentence.\\"]],\\n quiz:[[\\"Which SQL clause filters rows?\\",[\\"WHERE\\",\\"ORDER BY\\",\\"GROUP BY\\",\\"SELECT\\"],0,\\"WHERE keeps only the rows that match a condition.\\"],\\n       [\\"What is the median of 1, 3 and 9?\\",[\\"3\\",\\"4.3\\",\\"9\\",\\"13\\"],0,\\"Sorted, the middle value is 3. The mean would be 4.3.\\"],\\n       [\\"Which Python library is built for tables?\\",[\\"Pandas\\",\\"Flask\\",\\"Pygame\\",\\"Tkinter\\"],0,\\"Pandas gives you DataFrames for cleaning and summarising tables.\\"],\\n       [\\"What is overfitting?\\",[\\"A model that memorises training data and fails on new data\\",\\"A model that is too small\\",\\"Data that is too clean\\",\\"Training too fast\\"],0,\\"Always test on data the model has never seen.\\"],\\n       [\\"Best chart for change over time?\\",[\\"Line chart\\",\\"Pie chart\\",\\"Word cloud\\",\\"Bubble map\\"],0,\\"Lines show direction and pace across an ordered axis.\\"]],\\n pairs:[[\\"SQL\\",\\"Query databases\\"],[\\"Mean\\",\\"Average\\"],[\\"Median\\",\\"Middle value\\"],[\\"Pandas\\",\\"Python tables\\"],[\\"Outlier\\",\\"Odd extreme value\\"],[\\"CSV\\",\\"Comma text table\\"],[\\"Model\\",\\"Learned pattern\\"],[\\"Bias\\",\\"Systematic error\\"]],\\n words:[[\\"QUERY\\",\\"A question for a database\\"],[\\"MEDIAN\\",\\"The middle value\\"],[\\"PYTHON\\",\\"Language with Pandas\\"],[\\"CHART\\",\\"Data made visual\\"],[\\"OUTLIER\\",\\"An extreme value\\"]]},\\ndesign:{\\n read:[[\\"Type sets the tone\\",\\"Pick one or two typefaces and stick to them. Serif faces have small feet and feel traditional. Sans serif faces feel modern. Use size, weight and spacing, not more fonts, to show what matters.\\"],\\n       [\\"Contrast and hierarchy\\",\\"Readers scan before they read. Make the most important thing the biggest or boldest, group related things together, and keep text contrast high enough to read in daylight.\\"]],\\n quiz:[[\\"What does good colour contrast improve?\\",[\\"Readability\\",\\"Loading speed\\",\\"Search ranking\\",\\"File size\\"],0,\\"Higher contrast between text and background is easier to read.\\"],\\n       [\\"Which typeface is a serif?\\",[\\"Garamond\\",\\"Helvetica\\",\\"Arial\\",\\"Inter\\"],0,\\"Garamond has the small strokes called serifs.\\"],\\n       [\\"What is whitespace for?\\",[\\"Wasting space\\",\\"Giving content room and focus\\",\\"Only white colour\\",\\"Fixing bugs\\"],1,\\"Empty space groups things and guides the eye.\\"],\\n       [\\"What is a prototype?\\",[\\"A clickable mock of a product\\",\\"Final production code\\",\\"A logo file\\",\\"A brand guide\\"],0,\\"Prototypes let you test ideas before building them.\\"],\\n       [\\"Why test with real users?\\",[\\"To see where they struggle\\",\\"To choose colours\\",\\"To shorten code\\",\\"To win awards\\"],0,\\"Watching people reveals problems you cannot see yourself.\\"]],\\n pairs:[[\\"Serif\\",\\"Letters with feet\\"],[\\"Contrast\\",\\"Difference that aids reading\\"],[\\"Grid\\",\\"Layout skeleton\\"],[\\"Palette\\",\\"Set of colours\\"],[\\"Kerning\\",\\"Space between letters\\"],[\\"Wireframe\\",\\"Layout sketch\\"],[\\"Persona\\",\\"Imagined user\\"],[\\"Hierarchy\\",\\"Order of importance\\"]],\\n words:[[\\"KERNING\\",\\"Space between letters\\"],[\\"PALETTE\\",\\"A chosen set of colours\\"],[\\"WIREFRAME\\",\\"A rough layout sketch\\"],[\\"CONTRAST\\",\\"Difference between tones\\"],[\\"PERSONA\\",\\"A made-up typical user\\"]]}};\\n\\nconst KEY=\\"nightschool-v1\\";\\nlet S=JSON.parse(localStorage.getItem(KEY)||\\"null\\")||{xp:0,done:{},streak:0,last:\\"\\",quest:0,qok:\\"\\"};\\nS.read=S.read||{};\\nlet subj=\\"web\\",tab=\\"read\\",game=\\"memory\\";\\nconst save=()=>{try{localStorage.setItem(KEY,JSON.stringify(S))}catch(e){}};\\nconst shuffle=a=>{a=[...a];for(let i=a.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a};\\nfunction toast(m){const t=$(\\"#toast\\");t.textContent=m;t.classList.add(\\"show\\");clearTimeout(toast.h);toast.h=setTimeout(()=>t.classList.remove(\\"show\\"),2400)}\\nfunction xp(n,why){S.xp+=n;save();$(\\"#xp\\").textContent=`${S.xp} XP`;toast(`+${n} XP \\u00b7 ${why}`)}\\nfunction pills(el,obj,cur,fn){el.innerHTML=Object.entries(obj).map(([k,v])=>`<button class=\\"pill\\" data-k=\\"${k}\\" aria-pressed=\\"${k===cur}\\">${v}</button>`).join(\\"\\");el.onclick=e=>{const k=e.target.dataset.k;if(k)fn(k)}}\\nfunction nav(){\\n  pills($(\\"#subj\\"),SUBJ,subj,k=>{subj=k;nav();show()});\\n  pills($(\\"#tabs\\"),{read:\\"Read\\",quiz:\\"Quiz\\",games:\\"Games\\"},tab,k=>{tab=k;nav();show()});\\n  $(\\"#xp\\").textContent=`${S.xp} XP`;\\n}\\nfunction show(){({read,quiz:startQuiz,games:startGames})[tab]()}\\n\\n/* reading */\\nfunction read(){\\n  $(\\"#view\\").innerHTML=D[subj].read.map((r,i)=>{const id=subj+i,done=S.read[id];\\n    return`<article class=\\"card\\"><h2>${r[0]}</h2><p>${r[1]}</p><button class=\\"btn\\" data-id=\\"${id}\\" ${done?\\"disabled\\":\\"\\"}>${done?\\"Read\\":\\"Mark as read, +10 XP\\"}</button></article>`}).join(\\"\\");\\n  $(\\"#view\\").onclick=e=>{const id=e.target.dataset.id;if(id&&!S.read[id]){S.read[id]=1;e.target.disabled=true;e.target.textContent=\\"Read\\";xp(10,\\"Lesson read\\")}};\\n}\\n\\n/* quiz */\\nfunction startQuiz(){quiz(0,0)}\\nfunction quiz(i,score){\\n  const Q=D[subj].quiz,v=$(\\"#view\\");v.onclick=null;\\n  if(i>=Q.length){\\n    if(score)xp(score*10,\\"Quiz finished\\");\\n    v.innerHTML=`<div class=\\"card\\"><h2>You scored ${score} out of ${Q.length}</h2><p>${score===Q.length?\\"Perfect run. Try another subject.\\":\\"Read the lessons again, then retry for a better score.\\"}</p><button class=\\"btn\\" id=\\"again\\">Try again</button></div>`;\\n    $(\\"#again\\").onclick=startQuiz;return;\\n  }\\n  const q=Q[i];\\n  v.innerHTML=`<div class=\\"card\\"><div class=\\"meta\\">Question ${i+1} of ${Q.length}</div><h2>${q[0].replace(/</g,\\"&lt;\\")}</h2>${q[1].map((o,k)=>`<button class=\\"opt\\" data-k=\\"${k}\\">${o.replace(/</g,\\"&lt;\\")}</button>`).join(\\"\\")}<div id=\\"fb\\"></div></div>`;\\n  v.querySelectorAll(\\".opt\\").forEach(b=>b.onclick=()=>{\\n    const k=+b.dataset.k,ok=k===q[2];\\n    v.querySelectorAll(\\".opt\\").forEach((x,j)=>{x.disabled=true;if(j===q[2])x.classList.add(\\"good\\")});\\n    if(!ok)b.classList.add(\\"bad\\");\\n    $(\\"#fb\\").innerHTML=`<p class=\\"why\\">${ok?\\"Correct. \\":\\"Not quite. \\"}${q[3]}</p><button class=\\"btn\\" id=\\"nx\\">${i+1<Q.length?\\"Next question\\":\\"See score\\"}</button>`;\\n    $(\\"#nx\\").onclick=()=>quiz(i+1,score+(ok?1:0));$(\\"#nx\\").focus();\\n  });\\n}\\n\\n/* games */\\nfunction startGames(){\\n  $(\\"#view\\").innerHTML=`<div class=\\"pills\\" id=\\"gsel\\"></div><div id=\\"g\\"></div>`;\\n  pills($(\\"#gsel\\"),{memory:\\"Memory match\\",scramble:\\"Word scramble\\"},game,k=>{game=k;startGames()});\\n  game===\\"memory\\"?memory():scramble();\\n}\\nfunction memory(){\\n  const cards=shuffle(D[subj].pairs.flatMap(([a,b],i)=>[{t:a,p:i},{t:b,p:i}]));\\n  let open=[],moves=0,found=0,lock=false;\\n  $(\\"#g\\").innerHTML=`<div class=\\"card\\"><h2>Match each term with its meaning</h2><div class=\\"meta\\" id=\\"mv\\">Moves: 0</div><div class=\\"board\\" id=\\"bd\\"></div></div>`;\\n  const bd=$(\\"#bd\\");\\n  cards.forEach((c,i)=>{\\n    const b=document.createElement(\\"button\\");b.className=\\"tile\\";b.textContent=\\"?\\";b.setAttribute(\\"aria-label\\",\\"Hidden card\\");\\n    b.onclick=()=>{\\n      if(lock||b.classList.contains(\\"up\\")||b.classList.contains(\\"ok\\"))return;\\n      b.classList.add(\\"up\\");b.textContent=c.t;open.push([b,c]);\\n      if(open.length<2)return;\\n      moves++;$(\\"#mv\\").textContent=\\"Moves: \\"+moves;\\n      const [[b1,c1],[b2,c2]]=open;open=[];\\n      if(c1.p===c2.p){b1.className=b2.className=\\"tile ok\\";if(++found===cards.length/2)xp(Math.max(10,40-moves),\\"Memory match cleared\\")}\\n      else{lock=true;setTimeout(()=>{[b1,b2].forEach(x=>{x.className=\\"tile\\";x.textContent=\\"?\\"});lock=false},800)}\\n    };bd.appendChild(b);\\n  });\\n}\\nfunction scramble(){\\n  const W=shuffle(D[subj].words);let i=0,pts=0;\\n  const scr=w=>{let s;do{s=shuffle(w.split(\\"\\")).join(\\"\\")}while(s===w);return s};\\n  function round(){\\n    if(i>=W.length){$(\\"#g\\").innerHTML=`<div class=\\"card\\"><h2>Round over: ${pts} of ${W.length}</h2><button class=\\"btn\\" id=\\"ag\\">Play again</button></div>`;$(\\"#ag\\").onclick=scramble;return}\\n    const [w,h]=W[i];\\n    $(\\"#g\\").innerHTML=`<div class=\\"card\\"><div class=\\"meta\\">Word ${i+1} of ${W.length}</div><div class=\\"scr\\">${scr(w)}</div><p>Hint: ${h}</p><input id=\\"ans\\" autocomplete=\\"off\\" aria-label=\\"Your answer\\" placeholder=\\"Type the word\\"><button class=\\"btn\\" id=\\"ck\\">Check</button> <button class=\\"opt\\" id=\\"sk\\" style=\\"display:inline-block;width:auto\\">Skip</button></div>`;\\n    const inp=$(\\"#ans\\");inp.focus();\\n    const check=()=>{if(inp.value.trim().toUpperCase()===w){pts++;xp(10,\\"Word solved\\");i++;round()}else{inp.value=\\"\\";inp.placeholder=\\"Not it. Try again\\";}};\\n    $(\\"#ck\\").onclick=check;inp.onkeydown=e=>{if(e.key===\\"Enter\\")check()};\\n    $(\\"#sk\\").onclick=()=>{i++;round()};\\n  }\\n  round();\\n}\\nnav();show();\\n</script>\\n</body>\\n</html>\\n", "README.md": "# Nightschool\\n\\nA static learning dashboard: skill constellations, reading, quizzes and games.\\n\\n## Run\\nOpen `index.html` with the Live Server extension in VS Code, or just double-click it.\\n\\n## Publish\\nPush to GitHub, then Settings > Pages > choose the `main` branch.\\n\\n## Customise\\nEdit `TRACKS` in `index.html` and the `D` object in `learn.html`.\\n"}')
os.makedirs("nightschool", exist_ok=True)
for name, text in files.items():
    with open(os.path.join("nightschool", name), "w", encoding="utf-8") as f:
        f.write(text)
    print("created nightschool/" + name)
print("\nDone. Next: code nightschool   (or File > Open Folder in VS Code)")
